mapper.select:
SELECT ID, KINDERGARTEN_ID, CLIENT, HOST, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT
WHERE KINDERGARTEN_ID = #{kindergartenId}

SELECT ID, KINDERGARTEN_ID, CLIENT, HOST, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT
WHERE CLIENT = #{client} OR HOST = #{host}

SELECT ID, KINDERGARTEN_ID, CLIENT, HOST, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT
WHERE ID = #{id}
